WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY end_date DESC NULLS LAST, id) AS dedup_rank FROM subscriptions) ranked WHERE dedup_rank = 1) SELECT CASE WHEN monthly_fee >= 224 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_tier, ROUND(SUM(monthly_fee) / NULLIF(COUNT(CASE WHEN status = 'ACTIVE' THEN 1 END), 0), 2) AS monthly_fee_per_active, ROUND(SUM(monthly_fee) / NULLIF(COUNT(CASE WHEN status = 'EXPIRED' THEN 1 END), 0), 2) AS monthly_fee_per_expired FROM deduped GROUP BY ROLLUP (CASE WHEN monthly_fee >= 224 THEN 'LARGE' ELSE 'SMALL' END) HAVING ROUND(SUM(monthly_fee) / NULLIF(COUNT(CASE WHEN status = 'ACTIVE' THEN 1 END), 0), 2) > 0 ORDER BY monthly_fee_per_expired
